CREATE TABLE city (
	id_city INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_city)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE collection_class (
	id_collection_class INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_collection_class)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE crs (
	id_crs INTEGER NOT NULL AUTO_INCREMENT, 
	epsg INTEGER, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_crs)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE dimension (
	id_dimension INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_dimension)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE link (
	id_link INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	url TEXT, 
	file_path TEXT, 
	accepted BOOL NOT NULL DEFAULT 0, 
	`SHA256` VARCHAR(64), 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_link)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE matrix (
	id_matrix INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	description TEXT, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_matrix)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE organization (
	id_organization INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	shorthand VARCHAR(64), 
	connection TEXT, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_organization)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE sop (
	id_sop INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	active BOOL NOT NULL DEFAULT 1, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_sop)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE action (
	id_action INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	iteration INTEGER, 
	active BOOL NOT NULL DEFAULT 1, 
	description TEXT, 
	id_sop INTEGER, 
	standard VARCHAR(255), 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_action), 
	FOREIGN KEY(id_sop) REFERENCES sop (id_sop)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE district (
	id_district INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	id_city INTEGER, 
	zip VARCHAR(16), 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_district), 
	FOREIGN KEY(id_city) REFERENCES city (id_city)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE j_sop_link (
	id_j_sop_link INTEGER NOT NULL AUTO_INCREMENT, 
	id_sop INTEGER NOT NULL, 
	id_link INTEGER NOT NULL, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_j_sop_link), 
	FOREIGN KEY(id_sop) REFERENCES sop (id_sop), 
	FOREIGN KEY(id_link) REFERENCES link (id_link)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE person (
	id_person INTEGER NOT NULL AUTO_INCREMENT, 
	id_organization INTEGER, 
	given_name VARCHAR(255), 
	surname VARCHAR(255) NOT NULL, 
	unix_account VARCHAR(64), 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_person), 
	FOREIGN KEY(id_organization) REFERENCES organization (id_organization), 
	UNIQUE (unix_account)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE unit (
	id_unit INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
