CREATE TABLE message (
	id_message INTEGER NOT NULL AUTO_INCREMENT, 
	sender INTEGER, 
	reciever INTEGER, 
	subject VARCHAR(255), 
	message TEXT, 
	`read` BOOL NOT NULL DEFAULT 0, 
	sent_at DATETIME, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_message), 
	FOREIGN KEY(sender) REFERENCES person (id_person), 
	FOREIGN KEY(reciever) REFERENCES person (id_person)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE street (
	id_street INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	id_district INTEGER, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_street), 
	FOREIGN KEY(id_district) REFERENCES district (id_district)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE task (
	id_task INTEGER NOT NULL AUTO_INCREMENT, 
	request VARCHAR(255) NOT NULL, 
	description TEXT, 
	id_assigner INTEGER, 
	id_assignee INTEGER, 
	deadline DATETIME, 
	done BOOL NOT NULL DEFAULT 0, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_task), 
	FOREIGN KEY(id_assigner) REFERENCES person (id_person), 
	FOREIGN KEY(id_assignee) REFERENCES person (id_person)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE unit_notation (
	id_unit_notation INTEGER NOT NULL AUTO_INCREMENT, 
	id_unit INTEGER NOT NULL, 
	notation VARCHAR(64) NOT NULL, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_unit_notation), 
	FOREIGN KEY(id_unit) REFERENCES unit (id_unit)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE house (
	id_house INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255), 
	number VARCHAR(16), 
	number_addition VARCHAR(16), 
	id_street INTEGER, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_house), 
	FOREIGN KEY(id_street) REFERENCES street (id_street)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE j_action_device (
	id_j_action_device INTEGER NOT NULL AUTO_INCREMENT, 
	id_action INTEGER NOT NULL, 
	id_device INTEGER NOT NULL, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_j_action_device), 
	FOREIGN KEY(id_action) REFERENCES action (id_action), 
	FOREIGN KEY(id_device) REFERENCES device (id_device)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE j_organization_house (
	id_j_organization_house INTEGER NOT NULL AUTO_INCREMENT, 
	id_organization INTEGER NOT NULL, 
	id_house INTEGER NOT NULL, 
	address_class VARCHAR(64), 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_j_organization_house), 
	FOREIGN KEY(id_organization) REFERENCES organization (id_organization), 
	FOREIGN KEY(id_house) REFERENCES house (id_house)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE j_person_house (
	id_j_person_house INTEGER NOT NULL AUTO_INCREMENT, 
	id_person INTEGER NOT NULL, 
	id_house INTEGER NOT NULL, 
	address_class VARCHAR(64), 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_j_person_house), 
	FOREIGN KEY(id_person) REFERENCES person (id_person), 
	FOREIGN KEY(id_house) REFERENCES house (id_house)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE site (
	id_site INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	id_house INTEGER, 
	borders POLYGON, 
	id_crs INTEGER, 
	description TEXT, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_site), 
	FOREIGN KEY(id_house) REFERENCES house (id_house), 
	FOREIGN KEY(id_crs) REFERENCES crs (id_crs)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE spot (
	id_spot INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(255) NOT NULL, 
	x DOUBLE, 
	y DOUBLE, 
	z DOUBLE, 
	z_class VARCHAR(64), 
	z_id_unit INTEGER, 
	id_crs INTEGER, 
	description TEXT, 
	id_site INTEGER, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_spot), 
	FOREIGN KEY(z_id_unit) REFERENCES unit (id_unit), 
	FOREIGN KEY(id_crs) REFERENCES crs (id_crs), 
	FOREIGN KEY(id_site) REFERENCES site (id_site)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE collection (
	id_collection INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(64) NOT NULL, 
	id_matrix INTEGER, 
	id_collection_class INTEGER, 
	id_spot INTEGER, 
	id_site INTEGER, 
	sampled_at DATETIME, 
	id_sampler INTEGER, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_collection), 
	UNIQUE (name), 
	FOREIGN KEY(id_matrix) REFERENCES matrix (id_matrix), 
	FOREIGN KEY(id_collection_class) REFERENCES collection_class (id_collection_class), 
	FOREIGN KEY(id_spot) REFERENCES spot (id_spot), 
	FOREIGN KEY(id_site) REFERENCES site (id_site), 
	FOREIGN KEY(id_sampler) REFERENCES person (id_person)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE value (
	id_value INTEGER NOT NULL AUTO_INCREMENT, 
	id_collection INTEGER NOT NULL, 
	id_j_action_variable INTEGER NOT NULL, 
	repetition INTEGER NOT NULL DEFAULT 1, 
	repetition_class VARCHAR(64), 
	decimal_value DOUBLE, 
	text_value TEXT, 
	boolean_value BOOL, 
	datetime_value DATETIME, 
	accepted BOOL NOT NULL DEFAULT 0, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_value), 
	FOREIGN KEY(id_collection) REFERENCES collection (id_collection), 
	FOREIGN KEY(id_j_action_variable) REFERENCES j_action_variable (id_j_action_variable)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE j_value_value (
	id_j_value_value INTEGER NOT NULL AUTO_INCREMENT, 
	id_value1 INTEGER NOT NULL, 
	id_value2 INTEGER NOT NULL, 
	PRIMARY KEY (id_j_value_value), 
	FOREIGN KEY(id_value1) REFERENCES value (id_value), 
	FOREIGN KEY(id_value2) REFERENCES value (id_value)
)ENGINE=InnoDB CHARSET=utf8mb4;

CREATE TABLE raw_value (
	id_raw_value INTEGER NOT NULL AUTO_INCREMENT, 
	id_value INTEGER NOT NULL, 
	t DATETIME NOT NULL, 
	id_person INTEGER, 
	id_device INTEGER, 
	decimal_raw_value DOUBLE, 
	text_raw_value TEXT, 
	boolean_raw_value BOOL, 
	datetime_raw_value DATETIME, 
	accepted BOOL NOT NULL DEFAULT 0, 
	vis BOOL NOT NULL DEFAULT 1, 
	PRIMARY KEY (id_raw_value), 
	FOREIGN KEY(id_value) REFERENCES value (id_value), 
	FOREIGN KEY(id_person) REFERENCES person (id_person), 
	FOREIGN KEY(id_device) REFERENCES device (id_device)
)ENGINE=InnoDB CHARSET=utf8mb4;
